command:
// Array of funny descriptions
let descriptions = [
	"🦋 Desna’s wings stir the air around you. A small choice, a huge ripple. Who does the starlight land on tonight? 🦋",
	"🌌 The night sky feels close enough to touch. Desna hums a wandering tune, and fate takes a single step forward. 🌌",
	"✨ A trail of silver stardust curls across your path. Desna nudges the moment, gentle as a dream. ✨",
	"🌙 Under Desna’s moonlit gaze, your footsteps feel lighter. One of you is about to be picked by the heavens. 🌙",
	"🧭 Desna smiles on travelers and the lost alike. The compass spins, slows, and settles on its answer. 🧭",
	"💫 A falling star scratches a bright line through the dark. Desna’s blessing arrives the way it always does: unexpectedly. 💫",
	"🕯️ The world goes quiet for half a heartbeat, like a dream holding its breath. Desna whispers, and someone is chosen. 🕯️",
	"🌠 You feel it before you see it. The constellation shifts. Desna rearranges the night to point at one soul. 🌠",
	"🦋 A butterfly circles once, twice, then vanishes into the gloom. Desna’s sign is subtle, but the choice won’t be. 🦋",
	"🌈 The horizon glows with impossible color, like a place you’ve never been but somehow remember. Desna guides the moment. 🌈",
	"🔮 The future doesn’t shout. It shimmers. Desna’s dreams curl around the edges of reality and pick their favorite. 🔮",
	"🎶 Somewhere far away, a traveler’s song drifts on the wind. Desna keeps the rhythm, and fate keeps time. 🎶",
	"🌟 The stars blink like they’re laughing at how serious you’re being. Desna’s luck is never random, just mysterious. 🌟",
	"🌜 In the hush between heartbeats, Desna’s moonlight brushes your shoulders. One name is about to glow brighter than the rest. 🌜"
];

// Pick tokens + randoms
const tokens = canvas.tokens.controlled;
const tokenNames = tokens.map(t => t.name);

if (tokenNames.length === 0) {
	ui.notifications.warn("no tokens selected.");
	return;
}

const randomDescription = descriptions[Math.floor(Math.random() * descriptions.length)];
const randomTokenName = tokenNames[Math.floor(Math.random() * tokenNames.length)];

// Smaller PF2e-themed card (Desna)
const logoPath = "systems/pf2e/icons/deities/desna.webp";

const cardStyle = `
	background-color:#1d1c1a;
	border: 2px solid #5f574e;
	box-shadow: 3px 3px 10px rgba(0, 0, 0, 0.6);
	border-radius: 12px;
	padding: 12px;
	color: #e4ddc7;
	font-family: 'serif';
	max-width: 420px;
	margin: auto;
`;

const hrStyle = `border: 1px solid #5f574e; margin: 10px 0;`;

const content = `
	<div style="${cardStyle}">
		<div style="display:flex; justify-content:center; align-items:center; margin-bottom:8px;">
        	<img src="${logoPath}" style="width:64px; height:64px; display:block;">
        </div>

        <div style="text-align:center; font-weight:bold; font-size:15px; letter-spacing:1px; color:#c7b26f; margin-bottom:8px;">
        	DESNA
        </div>

		<div style="font-size: 13px; font-style: italic; text-align:center; margin-bottom: 8px;">
			${randomDescription}
		</div>

		<hr style="${hrStyle}">

		<div style="font-size: 13px; text-align:center; margin-bottom: 6px;">
			<strong style="color:#e4ddc7;">The chosen is:</strong>
		</div>

		<div style="font-size: 20px; text-align:center; font-weight:bold; color:#c7b26f; letter-spacing:0.5px; margin: 8px 0 2px 0;">
			${randomTokenName}
		</div>

		<div style="font-size: 11px; font-style: italic; text-align:center; color:#a09888; margin-top: 8px;">
			The stars already knew. You just finally caught up.
		</div>

        <hr style="${hrStyle}">

        <div style="font-size: 12px; color:#a09888; text-align:center; margin-bottom: 8px;">
			<strong style="color:#e4ddc7;">Selected tokens:</strong> ${tokenNames.join(", ")}
		</div>

	</div>
`;

ChatMessage.create({ content });
